def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
        if history[i][0] == 'C':
            my_c += 1

    opp_d = n - opp_c
    my_d = n - my_c
    last_my = history[-1][0]
    last_opp = history[-1][1]

    r10_opp_d = 0
    r10_my_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            r10_opp_d += 1
        if history[i][0] == 'D':
            r10_my_d += 1

    r5_opp_c = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            r5_opp_c += 1

    after_d_d = 0
    after_d_c = 0
    after_c_d = 0
    after_c_c = 0
    start = n - 30
    if start < 1:
        start = 1
    for i in range(start, n):
        prev = history[i - 1][0]
        op = history[i][1]
        if prev == 'D':
            if op == 'D':
                after_d_d += 1
            else:
                after_d_c += 1
        else:
            if op == 'D':
                after_c_d += 1
            else:
                after_c_c += 1

    ad_tot = after_d_d + after_d_c
    ac_tot = after_c_d + after_c_c
    if ad_tot:
        p_ret = (after_d_d + 1.0) / (ad_tot + 2.0)
    else:
        p_ret = 0.5
    if ac_tot:
        p_spon = (after_c_d + 1.0) / (ac_tot + 2.0)
    else:
        p_spon = 0.5

    if n >= 99:
        return 'D'

    if opp_d == 0:
        return 'D' if n >= 12 else 'C'

    if opp_c == 0:
        return 'D'

    if my_d == 0 and last_opp == 'D' and opp_d <= 4 and n <= 30:
        return 'C'

    if opp_d * 3 >= n * 2 and n >= 12:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if p_ret > 0.55 and opp_c * 5 >= n * 3 and r10_opp_d <= 5:
                return 'C'
            if opp_c * 2 >= n and r10_opp_d <= 2:
                return 'C'
            return 'D'

        if (
            n >= 3
            and history[-2][0] == 'D'
            and history[-2][1] == 'C'
            and history[-3][0] == 'C'
            and history[-3][1] == 'D'
            and opp_c * 3 >= n * 2
        ):
            return 'C'

        if r10_opp_d >= 5:
            return 'D'

        if r10_my_d >= 3 and opp_c * 2 >= n:
            return 'C'

        if p_ret > 0.60 and p_spon < 0.40 and opp_c * 3 >= n * 2:
            return 'C'

        if p_spon > 0.45 and p_ret < 0.55:
            return 'D'

        if opp_c * 5 >= n * 4 and rng.random() < 0.18:
            return 'C'

        return 'D'

    if last_my == 'D':
        if opp_c * 2 >= n and r10_opp_d <= 4 and p_ret < 0.62:
            return 'D'
        return 'C'

    if my_d > 0 and ad_tot >= 2 and p_ret < 0.35 and opp_c * 5 >= n * 3 and r10_opp_d <= 3:
        return 'D'

    if my_d == 0 and 2 <= opp_d <= 4 and r5_opp_c >= 3 and n >= 18:
        return 'D'

    if n >= 88 and opp_c * 5 >= n * 3 and r10_opp_d <= 4:
        if p_ret < 0.50 or rng.random() < 0.20:
            return 'D'

    return 'C'
